analytics.subscribe('checkout_completed', (event) => {
  const { checkout } = event.data;
  fetch('https://seu-backend.com/track', {
    method: 'POST',
    body: JSON.stringify({
      orderId: checkout.order?.id,
      total: checkout.totalPrice?.amount
    })
  });
});

analytics.subscribe('product_viewed', (event) => track('product_viewed', event));
analytics.subscribe('checkout_started', (event) => track('checkout_started', event));
analytics.subscribe('checkout_completed', (event) => track('checkout_completed', event));

function track(name, event) {
  fetch('https://seu-backend.com/track', {
    method: 'POST',
    body: JSON.stringify({ name, data: event.data })
  });
}
